// Source of truth for the Off Localhost AgentSession copy: props/offlocalhost-session.json
// is GENERATED by this script; edit copy here, never in the JSON (it gets clobbered).
//
// The two MCP calls name real tools on the `offlocal` server (preflight_launch,
// check_domain_availability). Their names were taken from the live MCP tool list on
// 2026-09-03 by the session that commissioned this composition, not re-derived here;
// re-check them against a live `/mcp` before changing either string. An invented tool
// name is obvious to anyone who uses the product, so they are not to be paraphrased.
// The domain-purchase call ends in `hold`, not `success`: the brand rule
// is that orange means a hoop the human still has to jump through, and buying a domain
// is exactly that.
//
// Usage: node scripts/build-offlocalhost-session-props.mjs
import {spawnSync} from 'node:child_process';
import {writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname, join} from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const tool = (arg, pendingText, doneText, frames, extra = {}) => ({
  kind: 'tool',
  tool: 'Bash',
  server: null,
  arg,
  pendingText,
  doneText,
  frames,
  status: 'success',
  expandable: false,
  ...extra,
});

const session = {
  brandId: 'offlocalhost',
  header: {
    user: 'Wes',
    model: 'Opus 5 with high effort · Claude Max',
    cwd: '~/projects/sidetap',
    tips: [
      'Run /marketing to render the whole asset suite',
      'Run /launch to take the product live',
      'Everything is a dry run until you pass --live',
    ],
  },
  beats: [
    {kind: 'prompt', text: '/marketing sidetap'},
    {kind: 'say', text: 'Reading the brand from the repo, then filming the running app.'},
    {kind: 'think', verb: 'Onboarding', frames: 50},
    tool(
      'src/app/globals.css',
      'Reading…',
      '13 brand tokens and two fonts, written to brands/sidetap.json',
      30,
      {tool: 'Read', expandable: true},
    ),
    tool(
      'node scripts/build-storyboard.mjs sidetap',
      'Running…',
      'storyboard.html written, waiting for your content approval',
      32,
    ),
    tool(
      'npx remotion render LaunchVideo out/sidetap/launch-v1.mp4',
      'Rendering in background…',
      '1350 frames, 45 seconds, picture locked',
      72,
      {expandable: true},
    ),
    tool(
      'node scripts/score-film.mjs sidetap launch-v1.mp4',
      'Scoring…',
      '6 narration lines placed, music ducked under each, loudness mastered',
      64,
    ),
    tool('node scripts/judge-drift.mjs sidetap', 'Judging…', '7 of 7 judges passed', 30),
    {
      kind: 'say',
      text: 'Logo reveal, product demo, launch film and two social clips are in out/sidetap/. Nothing has left this machine.',
    },
    {kind: 'prompt', text: '/launch sidetap --domain sidetap.io'},
    tool(
      'launch init ../sidetap --domain sidetap.io',
      'Scanning…',
      'Wrote .launch/launch.config.json',
      28,
    ),
    tool('domain · vercel · stripe · resend', 'Checking…', '4 providers ready, no spend yet', 32, {
      tool: 'preflight_launch',
      server: 'offlocal',
    }),
    tool('sidetap.io', 'Checking…', 'Available. Purchase waits for your approval', 30, {
      tool: 'check_domain_availability',
      server: 'offlocal',
      status: 'hold',
    }),
    tool(
      'launch copy ../sidetap --validate',
      'Validating…',
      '7 drafts pass every platform\'s hard limits',
      30,
    ),
    tool(
      'launch post ../sidetap --all',
      'Dry run…',
      '7 posts staged with the videos attached, nothing published',
      68,
      {expandable: true},
    ),
    {
      kind: 'say',
      text: 'Dry run complete. Say --live and I post everywhere with an API. Hacker News and Product Hunt are staged; you press submit.',
    },
  ],
  cta: 'offlocalhost.com',
  command: null,
  endHoldFrames: 75,
};

const outPath = join(root, 'props', 'offlocalhost-session.json');
writeFileSync(outPath, JSON.stringify(session, null, 2) + '\n');
console.log('wrote props/offlocalhost-session.json');

// Every line above is on screen, so it goes through the same voice gate every other
// generated props file does. A copy edit that trips the linter must fail the build,
// not be discovered in a still.
const lint = spawnSync(process.execPath, [join(root, 'scripts', 'lint-copy.mjs'), outPath], {
  stdio: 'inherit',
});
if (lint.status !== 0) {
  console.error(`lint-copy FAILED on props/offlocalhost-session.json (exit ${lint.status})`);
  process.exit(lint.status ?? 1);
}
